function responsive_collection(string $kind):void{
 $rows=[
  'courses'=>[['Positivo Direto em Filme de Raio-X','3 turmas · 18 alunos','2 sem turma · 4 testes'],['Fotografia Experimental em Grande Formato','1 turma · 8 alunos','Nada pendente']],
