  'registrations'=>[['Carlos Pereira','Pago · sem turma','03/10/2026'],['Ana Souza','Pago · Outubro 2026','02/10/2026']],
  'students'=>[['Ana Souza','Conta ativa','Outubro 2026'],['Rafael Lima','Ativação pendente','Outubro 2026']],
  'questions'=>[['Tempo no primeiro revelador','Ana Souza','Aberta · 2 respostas'],['Reciprocidade','Rafael Lima','Resolvida']],
  'tests'=>[['EI 400 — Parodinal','Rafael Lima','Aguardando avaliação'],['EI 200 — Parodinal','Ana Souza','Revisado']],
  'material'=>[['Caderno do workshop','Publicado','3 aulas'],['Referências','Rascunho','Sempre disponível']],
  'people'=>[['Ana Souza','Ativa','2 matrículas'],['Rafael Lima','Pendente','1 matrícula']],
 ];
 $headers=match($kind){
  'courses'=>['Curso','Turmas e alunos','Precisa de atenção'],'cohorts'=>['Turma','Período','Resumo'],'registrations'=>['Pessoa','Status','Data'],
  'students'=>['Aluno','Conta','Participação'],'questions'=>['Dúvida','Aluno','Status'],'tests'=>['Teste','Aluno','Estado'],
  'material'=>['Página','Status','Disponibilidade'],'people'=>['Pessoa','Conta','Histórico'],default=>['Item','Estado','Detalhe']
 };
 echo '<div class="admin-table-scroll" tabindex="0"><table class="admin-data-table admin-responsive-list"><thead><tr>';
 foreach($headers as $h)echo '<th>'.h($h).'</th>';echo '<th></th></tr></thead><tbody>';
 foreach($rows[$kind]??[] as $row){echo '<tr>';
   foreach($row as $i=>$value)echo '<td '.($i===0?'data-primary="true" ':'').'data-label="'.h($headers[$i]).'">'.($i===0?'<div class="admin-table-primary"><strong>'.h($value).'</strong><span>Contexto administrativo</span></div>':h($value)).'</td>';
   echo '<td data-actions="true" class="actions"><a class="admin-button secondary admin-table-action" href="#">Abrir</a></td></tr>';
 }echo '</tbody></table></div>';
}
